"""Synthetic-only SOVIA buyer sample generated by actual audit engine, never a screenshot."""
from __future__ import annotations

import copy
import hashlib
import json
from pathlib import Path
import re
import socket
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import sovia_demo_pack as demo
import sovia_audit as audit


class DemoPackTests(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.root = Path(tmp.name)
        self.output = self.root / "sample"

    def cli(self, out=None, ack=True):
        args = [sys.executable, "-I", "-B", str(ROOT / "sovia_demo_pack.py"),
                "--output-dir", str(self.output if out is None else out)]
        if ack:
            args.append("--synthetic-only")
        return subprocess.run(args, capture_output=True, text=True, timeout=25)

    def test_real_engine_generates_expected_four_artifacts(self):
        x = demo.write_package(self.output)
        self.assertEqual(4, x["file_count"])
        self.assertEqual((3, 5), (x["synthetic_events"], x["synthetic_findings"]))
        self.assertEqual(set(demo.FILES), {p.name for p in self.output.iterdir()})
        self.assertFalse(x["commercial_release_approved"])

    def test_real_engine_output_matches_fixed_fixture(self):
        demo.write_package(self.output)
        generated = json.loads((self.output / demo.FILES[1]).read_text(encoding="utf-8"))
        exact = audit.evaluate(audit.read_document(ROOT / "examples" / demo.FIXTURE))
        self.assertEqual(exact, generated["report"])
        self.assertEqual("SAMPLE_SYNTHETIC_NOT_CUSTOMER_EVIDENCE", generated["watermark"])

    def test_five_rule_names_and_no_fabricated_findings(self):
        demo.write_package(self.output)
        report = json.loads((self.output / demo.FILES[1]).read_text(encoding="utf-8"))["report"]
        self.assertEqual(demo.EXPECTED_RULES, {x["rule_id"] for x in report["findings"]})
        self.assertEqual(5, report["finding_count"])
        self.assertTrue(any(x["evidence_status"] == "POINTER_MISSING" for x in report["findings"]))

    def test_buyer_html_has_prominent_visible_and_print_watermark(self):
        demo.write_package(self.output)
        html = (self.output / demo.FILES[0]).read_text(encoding="utf-8")
        self.assertEqual(1, html.count(demo.LABEL))
        self.assertIn("sovia-sample-banner", html)
        self.assertIn("@media print", html)
        self.assertIn("display:block!important", html)
        self.assertIn("SOVIA Audit Lite", html)
        self.assertIn("검토 이벤트 3건 · 위험 소견 5건", html)

    def test_sample_html_is_standalone_and_offline_policy(self):
        demo.write_package(self.output)
        page = (self.output / demo.FILES[0]).read_text(encoding="utf-8")
        self.assertIn("Content-Security-Policy", page)
        for token in ("default-src 'none'", "script-src 'none'", "connect-src 'none'",
                      "img-src 'none'", "object-src 'none'"):
            self.assertIn(token, page)
        for bad in ("<script", "<iframe", "<img", "http://", "https://",
                    "fetch(", "XMLHttpRequest", "<link"):
            self.assertNotIn(bad, page)

    def test_sample_json_never_advertises_real_origin_or_release(self):
        demo.write_package(self.output)
        wrapped = json.loads((self.output / demo.FILES[1]).read_text(encoding="utf-8"))
        for key in ("customer_records_processed", "real_n8n_integration_verified",
                    "owner_device_or_security_certified", "commercial_release_approved"):
            self.assertFalse(wrapped[key])
        self.assertEqual("sovia.synthetic_sales_sample.v1", wrapped["format"])

    def test_unsigned_manifest_matches_exact_report_bytes(self):
        demo.write_package(self.output)
        meta = json.loads((self.output / demo.FILES[3]).read_text(encoding="utf-8"))
        self.assertFalse(meta["independent_origin_authenticated"])
        self.assertFalse(meta["commercial_release_approved"])
        self.assertEqual(set(demo.FILES[:3]), set(meta["files"]))
        for file, item in meta["files"].items():
            b = (self.output / file).read_bytes()
            self.assertEqual(len(b), item["bytes"])
            self.assertEqual(hashlib.sha256(b).hexdigest(), item["sha256"])

    def test_manifest_is_unsigned_not_independent_publisher_auth(self):
        meta = json.loads(demo.render_package()[demo.FILES[3]].decode("utf-8"))
        self.assertEqual("UNSIGNED_SAMPLE_ONLY_NOT_A_RELEASE", meta["status"])
        self.assertTrue(meta["synthetic_only"])
        self.assertNotIn("signature", meta)
        self.assertNotIn("public_key", meta)

    def test_text_discloses_no_real_customer_input_or_sales_permission(self):
        doc = demo.render_package()[demo.FILES[2]].decode("utf-8")
        self.assertIn("SAMPLE", doc)
        self.assertIn("NOT A CUSTOMER AUDIT", doc)
        self.assertIn("합성 예시", doc)
        self.assertIn("not legal evidence", doc.lower())
        self.assertIn("Screenshots", doc)

    def test_output_deterministic_bytes_across_two_generations(self):
        before = demo.render_package()
        after = demo.render_package()
        self.assertEqual(before, after)
        self.assertEqual(set(demo.FILES), set(before))

    def test_missing_ack_fail_closed_without_folder(self):
        c = self.cli(ack=False)
        self.assertEqual(2, c.returncode)
        self.assertFalse(self.output.exists())
        self.assertIn("SYNTHETIC_ONLY_ACK_REQUIRED", c.stderr)

    def test_cli_success_has_no_published_or_customer_claims(self):
        c = self.cli()
        self.assertEqual(0, c.returncode, c.stderr)
        result = json.loads(c.stdout)
        self.assertEqual("SYNTHETIC_SAMPLE_FILES_CREATED_NOT_PUBLISHED", result["status"])
        for key in ("commercial_release_approved", "customer_evidence_or_authorization_verified",
                    "real_n8n_compatibility_verified", "real_owner_windows_or_browser_verified",
                    "manifest_is_signed", "network_called"):
            self.assertFalse(result[key])

    def test_existing_output_folder_refused_without_file_change(self):
        self.output.mkdir()
        existing = self.output / "important.txt"
        existing.write_text("KEEP", encoding="utf-8")
        c = self.cli()
        self.assertEqual(2, c.returncode)
        self.assertEqual("KEEP", existing.read_text(encoding="utf-8"))

    def test_existing_directory_even_empty_refused(self):
        self.output.mkdir()
        with self.assertRaisesRegex(demo.SamplePackError, "NEW_OUTPUT_DIRECTORY_REQUIRED"):
            demo.write_package(self.output)

    def test_existing_regular_file_as_output_refused(self):
        self.output.write_text("KEEP", encoding="utf-8")
        with self.assertRaisesRegex(demo.SamplePackError, "NEW_OUTPUT_DIRECTORY_REQUIRED"):
            demo.write_package(self.output)
        self.assertEqual("KEEP", self.output.read_text(encoding="utf-8"))

    def test_missing_parent_refused_with_no_directory_created(self):
        deep = self.root / "unknown" / "sample"
        c = self.cli(out=deep)
        self.assertEqual(2, c.returncode)
        self.assertFalse((self.root / "unknown").exists())

    def test_output_parent_symlink_rejected(self):
        actual = self.root / "actual"
        actual.mkdir()
        link = self.root / "symbol"
        try:
            link.symlink_to(actual, target_is_directory=True)
        except (OSError, NotImplementedError):
            self.skipTest("symlink unsupported on host")
        c = self.cli(out=link / "sample")
        self.assertEqual(2, c.returncode)
        self.assertEqual([], list(actual.iterdir()))

    def test_output_path_symlink_rejected(self):
        other = self.root / "other"
        other.mkdir()
        try:
            self.output.symlink_to(other, target_is_directory=True)
        except (OSError, NotImplementedError):
            self.skipTest("symlink unsupported on host")
        c = self.cli()
        self.assertEqual(2, c.returncode)
        self.assertEqual([], list(other.iterdir()))

    def test_unknown_fixture_keys_are_not_allowed(self):
        changed = copy.deepcopy(demo.EXPECTED)
        changed["events"][0]["prompt"] = "private"
        self.assertNotEqual(demo.EXPECTED, changed)
        self.assertEqual(3, len(demo.EXPECTED["events"]))

    def test_private_fixture_swap_is_refused_without_output(self):
        original = demo._audit
        fake_doc = copy.deepcopy(demo.EXPECTED)
        fake_doc["events"][0]["source_pointer"] = "private"
        class Audit:
            @staticmethod
            def read_document(_path):
                return fake_doc
        with patch.object(demo, "_audit", return_value=Audit()):
            with self.assertRaisesRegex(demo.SamplePackError, "FIXTURE_NOT_EXACT_FABRICATED_SAMPLE"):
                demo.write_package(self.output)
        self.assertFalse(self.output.exists())

    def test_missing_fixture_is_generic_error_and_no_output(self):
        class Audit:
            @staticmethod
            def read_document(_path):
                raise OSError("secret path")
        with patch.object(demo, "_audit", return_value=Audit()):
            with self.assertRaisesRegex(demo.SamplePackError, "FIXTURE_UNAVAILABLE_OR_INVALID"):
                demo.write_package(self.output)
        self.assertFalse(self.output.exists())

    def test_wrong_rule_count_blocks_pack(self):
        class Audit:
            @staticmethod
            def read_document(_path):
                return demo.EXPECTED
            @staticmethod
            def evaluate(_doc):
                return {"event_count": 0, "finding_count": 0, "events": [], "findings": []}
        with patch.object(demo, "_audit", return_value=Audit()):
            with self.assertRaisesRegex(demo.SamplePackError, "SAMPLE_AUDIT_EXPECTATIONS_CHANGED"):
                demo.write_package(self.output)
        self.assertFalse(self.output.exists())

    def test_writer_failure_does_not_leave_misleading_completed_folder(self):
        original_audit = demo._audit
        real = original_audit()
        def fake_write(_items):
            raise OSError("unexpected storage failure /secret")
        with patch.object(real, "write_reports_atomically", side_effect=fake_write), patch.object(
            demo, "_audit", return_value=real
        ):
            with self.assertRaisesRegex(demo.SamplePackError, "SAMPLE_OUTPUT_REJECTED"):
                demo.write_package(self.output)
        self.assertFalse(self.output.exists())

    def test_no_overwrite_on_repeat_generation(self):
        demo.write_package(self.output)
        orig = {(p.name, hashlib.sha256(p.read_bytes()).hexdigest())
                for p in self.output.iterdir()}
        c = self.cli()
        self.assertEqual(2, c.returncode)
        self.assertEqual(orig, {(p.name, hashlib.sha256(p.read_bytes()).hexdigest())
                                for p in self.output.iterdir()})

    def test_no_network_during_generation(self):
        with patch.object(socket.socket, "connect", side_effect=AssertionError("network forbidden")):
            report = demo.write_package(self.output)
        self.assertFalse(report["network_called"])

    def test_generates_utf8_korean_and_no_bom_errors(self):
        demo.write_package(self.output)
        for name in demo.FILES[:3]:
            data = (self.output / name).read_bytes()
            self.assertFalse(data.startswith(b"\xef\xbb\xbf"))
            self.assertIn("합성".encode("utf-8"),
                          data if name != demo.FILES[1] else
                          (self.output / demo.FILES[2]).read_bytes())

    def test_readme_cannot_imply_customer_case(self):
        demo.write_package(self.output)
        scope = (self.output / demo.FILES[2]).read_text(encoding="utf-8")
        self.assertIn("not a", scope.lower())
        self.assertIn("고객 감사 결과나 판매 승인 자료가 아닙니다", scope)
        self.assertIn("does not upload", scope.lower())

    def test_demo_bundle_not_added_to_original_portable_file_list(self):
        from build_portable import FILES as portable_files
        self.assertFalse(any("sovia_demo_pack.py" in path for path in portable_files))
        self.assertEqual(12, len(portable_files))

    def test_no_global_environment_needed(self):
        # Pure in-memory stage works without creating output or reading secrets.
        out = demo.render_package()
        self.assertEqual(4, len(out))
        self.assertFalse(self.output.exists())


if __name__ == "__main__":
    unittest.main()
